function getNextWeekdayDateString(from = DateTime.now()) {
	let date = from;
	while (date.weekday >= 6) date = date.plus({ days: 1 });
	return date.toFormat(luxonDayStringFormat);
}
function getNextWeekdayAfter(dateString) {
	let date = DateTime.fromFormat(dateString, luxonDayStringFormat).plus({ days: 1 });
	while (date.weekday >= 6) date = date.plus({ days: 1 });
	return date.toFormat(luxonDayStringFormat);
}
